662	
663	    // white 4-point flares carried by the current: along the flow in the mid field, across it near
664	    #ifdef LOW_Q
665	    vec2 g5 = vec2(wq * 6.0, v5 * 0.25);
666	    float hs5 = hash12(floor(g5));
667	    c5 += vec3(1.3) * step(0.88, hs5) * smoothstep(0.22, 0.0, length(fract(g5) - 0.5)) * (0.5 + 0.5 * sin(uTime * 7.0 + hs5 * 40.0));
668	    vec2 g5n = vec2(lat * 3.0, v5 * 2.4);
669	    float hs5n = hash12(floor(g5n) + 3.0);
670	    c5 += vec3(1.4) * near5 * step(0.6, hs5n) * smoothstep(0.16, 0.0, length(fract(g5n) - 0.5)) * (0.6 + 0.4 * sin(uTime * 6.0 + hs5n * 30.0));
