689	    c5 += mix(vec3(0.6, 1.6, 2.3), vec3(2.3, 1.6, 2.2), pinkM) * lzM * (1.0 - near5) * (1.0 - smoothstep(0.15, 0.4, fws)) * 1.1;
690	    flC *= 0.5 + 0.8 * cN;                      // the small stars cluster on the glossy lanes (not a uniform snow)
691	    float flD = flowGlint(vec2(wq * 16.0, v5 * 0.32 + 7.0), 0.5, 6.0, 2.4, 0.3, uTime + 4.1);
692	    // (the big near flares sit mostly on the swell crests: light catching the heaving surface)
693	    // (it05: the pink ribbons sparkle too, pink-white — ref 05 mid bands are full of bright glints)
694	    c5 += mix(vec3(1.9, 2.1, 2.3), vec3(2.3, 1.7, 2.2), pinkM) * (flA * (1.0 - near5) * (1.0 - smoothstep(0.3, 0.8, fws))
