700	  // ---- soap-foam lace where the water meets the foam banks ----
701	  float edgeN = (vnoise(vec2(s * 1.3, u * 2.0)) - 0.5) * 0.1;
702	  float eu = abs(lat) - vHalfW;               // units from the edge (negative inside)
703	  float edge = smoothstep(-0.75, -0.3, eu + edgeN * vHalfW);
704	  if (edge > 0.0) {
705	    float c = cells(vec2(lat * 3.2, (s - vSpeed * uTime * 0.35) * 3.2));
706	    vec3 foamCol = mix(uFoam * 1.15, uFoamLav * 0.85, smoothstep(0.25, 0.75, c));
