709	  col = mix(col, uFoamLav * 0.92, vSkirt);
710	  float cutC = cells(vec2(u * vHalfW * 4.0, s * 3.6));
711	  col = mix(col, mix(uFoam * 1.2, uFoamLav * 0.8, smoothstep(0.2, 0.7, cutC)), cutFoam);
712	
713	  // ---- Benny: ripple rings and a V wake on the surface ----
714	  // (the 3D splash crown, spray fan and foam belong to riderSplash/spray/foam; here the water
715	  // around and behind him stays glossy electric cyan as in ref 05.) There is deliberately NO white
716	  // contact band at the waterline: the old contact -> uFoam mix drew a white elliptical rim that the
717	  // fur fringe turned into the jagged "splash artifact" under Benny (wave-3 correction 7). Only a
718	  // faint cyan brightening marks the waterline.
719	  if (uBenny.z > 0.0) {
720	    float du = lat - uBenny.y;
721	    float dv = s - uBenny.x;
722	    float rb = uBennyR;
723	    float d = length(vec2(du, dv));
724	    if (d < rb * 8.0) {
725	      float k = uBenny.z;
726	      float rr = max(0.0, d - rb * 0.92);
727	      float rings = smoothstep(0.75, 1.0, 0.5 + 0.5 * sin(d * 5.0 - uTime * 9.0)) * exp(-rr * 0.55) * smoothstep(rb, rb * 1.3, d);
728	      // 05 (wave 7): no rings and no V lines — in the magnified near field they drew "∩" pool-ripple
729	      // arcs; the diagonal pink wake sweeps + fanning speed streaks carry the wake there instead
730	      rings *= 1.0 - sw;
731	      float bk = max(-dv, 0.0);
732	      float wakeV = exp(-abs(abs(du) - bk * 0.42 - rb * 0.95) * 6.0) * exp(-bk * 0.18) * step(dv, 0.0) * (1.0 - sw);
733	      col += uCyanBright * 0.18 * (1.0 - smoothstep(0.0, rb * 0.3, rr)) * k;
734	      col += mix(uCyanBright, vec3(1.3), 0.4) * (rings * 0.22 + wakeV * 0.35) * k * (1.0 - pinkM * 0.5);
735	    }
736	  }
737	
738	  // 04: exactly five glowing chevrons pointing downhill (direction of travel)
739	  if (uChevron.z > 0.5) {
740	    float x = u * vHalfW;
741	    for (int k = 0; k < 5; k++) {

741	    for (int k = 0; k < 5; k++) {
742	      float y = s - (uChevron.x + float(k) * uChevron.y);
743	      if (abs(y) < 2.4 && abs(x) < 1.6) {
744	        // "^" pointing toward +s: tip at y=+1.0, arms sweep back 1.9 units over ±1.15 lateral
745	        float dist = abs(y - (1.0 - abs(x) * 1.65)) * 0.52;
746	        float arm = smoothstep(1.2, 1.1, abs(x));
747	        float core = smoothstep(0.2, 0.11, dist) * arm;
748	        float halo = smoothstep(0.7, 0.0, dist) * smoothstep(1.5, 0.9, abs(x)) * 0.5;
