759	export interface Ribbon {
760	  mesh: THREE.Mesh;
761	  uniforms: Record<string, THREE.IUniform>;
762	  s0: number;
763	  s1: number;
764	  heightAt(s: number, lateral: number, t: number): number;
765	}
766	
767	export function createRibbon(course: Course, opts: { s0: number; s1: number; quality: 'high' | 'low' }): Ribbon {
768	  const { s0, s1, quality } = opts;
769	  const ds = quality === 'high' ? 0.4 : 0.7;
770	  const cols = quality === 'high' ? 18 : 10;
771	  const rows = Math.ceil((s1 - s0) / ds) + 1;
772	  const vertsPerRow = cols + 1 + 2; // + skirt left/right
773	  const n = rows * vertsPerRow;
774	  const pos = new Float32Array(n * 3);
775	  const nor = new Float32Array(n * 3);
776	  const uv = new Float32Array(n * 2);
777	  const halfW = new Float32Array(n);
778	  const speed = new Float32Array(n);
779	  const amp = new Float32Array(n);
780	  const skirt = new Float32Array(n);
781	  const style = new Float32Array(n * 4);
782	  const core = new Float32Array(n);
783	  const tang = new Float32Array(n * 3);
784	  const tmp = new THREE.Vector3();
785	  const nrm = new THREE.Vector3();
786	  let k = 0;
787	  for (let i = 0; i < rows; i++) {
788	    const s = Math.min(s1, s0 + i * ds);
789	    const f = course.sample(s);
790	    const hw = course.widthAt(s) / 2;
791	    const sp = Math.max(3, course.prop(s, 'speed'));
792	    const a = ampAt(course, s);
793	    const bs = bandStyleAt(course, s);
794	    const cl = coreLateral(course, s);
795	    const put = (u: number, lateral: number, h: number, isSkirt: number, nn: THREE.Vector3) => {
796	      tmp.copy(f.pos).addScaledVector(f.right, lateral).addScaledVector(f.up, h);
797	      tmp.toArray(pos, k * 3);
798	      nn.toArray(nor, k * 3);
799	      f.tan.toArray(tang, k * 3);
800	      uv[k * 2] = u;
801	      uv[k * 2 + 1] = s;
802	      halfW[k] = hw;
803	      speed[k] = sp;
804	      amp[k] = a;
805	      skirt[k] = isSkirt;
806	      for (let q = 0; q < 4; q++) style[k * 4 + q] = bs[q];
807	      core[k] = cl;
808	      k++;
809	    };
810	    // left skirt (below left edge)
811	    put(-1, -hw * 1.01, EDGE_LIFT - 0.7, 1, nrm.copy(f.right).negate());
812	    for (let j = 0; j <= cols; j++) {
813	      const u = -1 + (2 * j) / cols;
814	      const lift = EDGE_LIFT * Math.abs(u) ** 3;
815	      const slope = (EDGE_LIFT * 3 * u * Math.abs(u)) / hw; // d lift / d lateral
816	      nrm.copy(f.up).addScaledVector(f.right, -slope).normalize();
817	      put(u, u * hw, lift, 0, nrm);
818	    }
819	    put(1, hw * 1.01, EDGE_LIFT - 0.7, 1, nrm.copy(f.right));
820	  }
821	  const idx: number[] = [];
822	  for (let i = 0; i < rows - 1; i++) {
823	    for (let j = 0; j < vertsPerRow - 1; j++) {
824	      const a = i * vertsPerRow + j, b = a + 1, c = a + vertsPerRow, d = c + 1;
825	      idx.push(a, c, b, b, c, d);
826	    }
827	  }
828	  const geo = new THREE.BufferGeometry();
829	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
830	  geo.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
831	  geo.setAttribute('aUV', new THREE.BufferAttribute(uv, 2));
832	  geo.setAttribute('aHalfW', new THREE.BufferAttribute(halfW, 1));
833	  geo.setAttribute('aSpeed', new THREE.BufferAttribute(speed, 1));
834	  geo.setAttribute('aAmp', new THREE.BufferAttribute(amp, 1));
835	  geo.setAttribute('aSkirt', new THREE.BufferAttribute(skirt, 1));
836	  geo.setAttribute('aStyle', new THREE.BufferAttribute(style, 4));
837	  geo.setAttribute('aCore', new THREE.BufferAttribute(core, 1));
838	  geo.setAttribute('aTan', new THREE.BufferAttribute(tang, 3));
839	  geo.setIndex(idx);
840	  geo.computeBoundingSphere();
841	
842	  const st03 = course.stage('03'), st04 = course.stage('04'), st08 = course.stage('08');
843	  const uniforms = withFog({
844	    uTime: { value: 0 },
845	    uCyanDeep: { value: RIBBON_PAL.cyanDeep.clone() },
846	    uCyan: { value: RIBBON_PAL.cyan.clone() },
847	    uCyanBright: { value: RIBBON_PAL.cyanBright.clone() },
848	    uPinkDeep: { value: RIBBON_PAL.pinkDeep.clone() },
849	    uPink: { value: RIBBON_PAL.pink.clone() },
850	    uPinkLight: { value: RIBBON_PAL.pinkLight.clone() },
851	    uFoam: { value: PALETTE.foam.clone() },
852	    uFoamLav: { value: PALETTE.foamLav.clone() },
853	    uHaze: { value: PALETTE.haze.clone() },
854	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
855	    uBenny: { value: new THREE.Vector3(0, 0, 0) },
856	    uBennyR: { value: 0.7 },
857	    uChevron: { value: new THREE.Vector3(st04.s0 + 8.5, 3.6, 1) },
858	    uOutro: { value: new THREE.Vector2(0, st08.s0) },
859	    uHide: { value: new THREE.Vector4(st03.s0, st04.s0, 0, 0) },
860	    uC5Deep: { value: RIVER05_PAL.cyanDeep.clone() },
861	    uC5: { value: RIVER05_PAL.cyan.clone() },
862	    uC5Bright: { value: RIVER05_PAL.cyanBright.clone() },
863	    uC5Streak: { value: RIVER05_PAL.cyanStreak.clone() },
864	    uP5Deep: { value: RIVER05_PAL.pinkDeep.clone() },
865	    uP5: { value: RIVER05_PAL.pink.clone() },
866	    uP5Light: { value: RIVER05_PAL.pinkLight.clone() },
867	    uP5Streak: { value: RIVER05_PAL.pinkStreak.clone() },
868	    uFlow05: { value: course.stage('05').speed * FLOW05 },
869	  });
870	  const mat = new THREE.ShaderMaterial({
871	    uniforms,
872	    vertexShader: VERT,
873	    fragmentShader: FRAG,
874	    fog: true,
875	    side: THREE.DoubleSide,
876	    defines: quality === 'low' ? { LOW_Q: 1 } : {},
877	  });
878	  const mesh = new THREE.Mesh(geo, mat);
879	  mesh.name = 'water_ribbon';
880	  mesh.frustumCulled = false; // one long mesh spanning the whole course
881	  return {
882	    mesh,
883	    uniforms,
884	    s0,
885	    s1,
886	    heightAt(s, lateral, t) {
887	      const hw = course.widthAt(s) / 2;
888	      return ribbonWave(lateral / hw, s, t, ampAt(course, s));
889	    },
890	  };
891	}
