111	// Derivatives are taken before the early-out (Android-safe).
112	float lensFlare(vec2 g, float density, float Lpx, float Tpx, float time) {
113	  vec2 gx = dFdx(g);
114	  vec2 gy = dFdy(g);
115	  vec2 gi = floor(g);
116	  float hs = hash12(gi + 4.17);
117	  float det = gx.x * gy.y - gy.x * gx.y;
118	  if (hs < 1.0 - density || abs(det) < 1e-12) return 0.0;
