122	  float limy = 0.3 / max(abs(gy.x) + abs(gy.y), 1e-6);
123	  float L = min(Lpx * (0.55 + 0.9 * fract(hs * 37.0)), limx);
124	  float T = min(Tpx * (0.7 + 0.6 * fract(hs * 53.0)), limy * 0.5);
125	  float x = p.x / L;
126	  if (abs(x) > 1.0) return 0.0;
127	  float y = p.y - 0.35 * T * (1.0 - x * x);       // slight arch
128	  float th = T * (1.0 - x * x);
129	  float lens = 1.0 - smoothstep(th * 0.6, th + 1.0, abs(y));
130	  float glow = exp(-abs(y) / (T * 2.2 + 1.0)) * (1.0 - abs(x));
